import test from 'node:test';
import assert from 'node:assert/strict';
import { formatLabel, decoratedLabel } from '../src/format-label.js';
test('format valid label and preserve case', t => { assert.equal(formatLabel('MiXeD'), 'MiXeD'); t.diagnostic('BODY:format-valid'); });
test('decorate with configured suffix', t => { assert.equal(decoratedLabel('hello'), 'hello!'); t.diagnostic('BODY:format-config'); });
test('trim surrounding whitespace while preserving case and internal spaces', () => {
  assert.equal(formatLabel(' \tMiXeD Case\n'), 'MiXeD Case');
  assert.equal(decoratedLabel(' \tMiXeD Case\n'), 'MiXeD Case!');
});
for (const value of ['', '   ', '\t\n']) {
  test(`reject blank label ${JSON.stringify(value)}`, () => {
    assert.throws(() => formatLabel(value), /blank label/);
    assert.throws(() => decoratedLabel(value), /blank label/);
  });
}

